# ---------------- writer + assertions + self-verify ----------------
def main():
    ids = B03 + B04
    assert len(ids) == 40 and len(set(ids)) == 40, "batch id list must be 40 unique"
    got = [p["case_id"] for p in P]
    assert len(got) == 40, f"predictions count {len(got)} != 40"
    assert set(got) == set(ids), f"id set mismatch: missing={set(ids)-set(got)} extra={set(got)-set(ids)}"
    OUT.mkdir(parents=True, exist_ok=True)
    total_bytes = 0
    for p in P:
        assert set(p.keys()) == {"case_id","prediction_text","basis","confidence","trigger"}, p["case_id"]
        assert set(p["trigger"].keys()) == {"changed_main","reserve_used","disputed","reason"}, p["case_id"]
        assert isinstance(p["confidence"], float) and 0.0 <= p["confidence"] <= 1.0, p["case_id"]
        fp = OUT / (p["case_id"] + ".json")
        data = json.dumps(p, ensure_ascii=False, indent=1).encode("utf-8")
        fp.write_bytes(data)
        total_bytes += len(data)
    # read-back verification, exact per-id only
    ok = 0
    ly = [p for p in P if p["case_id"].startswith("BQ-")]
    cm = sum(1 for p in ly if p["trigger"]["changed_main"])
    ru = sum(1 for p in ly if p["trigger"]["reserve_used"])
    di = sum(1 for p in ly if p["trigger"]["disputed"])
    for cid in ids:
        fp = OUT / (cid + ".json")
        d = json.loads(fp.read_text(encoding="utf-8"))
        assert d["case_id"] == cid and d["prediction_text"] and d["basis"], cid
        ok += 1
    print(f"WROTE {ok} files, total_bytes={total_bytes}")
    print(f"LIUYAO n={len(ly)} changed_main={cm} reserve_used={ru} disputed={di}")

if __name__ == "__main__":
    main()
